export function assertTestAuthLoopbackOnly(
  flags: readonly string[],
  bindHost: string,
  env: NodeJS.ProcessEnv = process.env,
): void {
  const any = flags.some((f) => env[f] === "1");
  if (!any) return;
  const loopback =
    bindHost === "127.0.0.1" || bindHost === "::1" || bindHost === "localhost";
